#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    if(scanf("%d",&n)!=1) return 0;
    vector<vector<int>> adj(n+1);
    for(int i=0;i<n-1;i++){
        int x,y; scanf("%d %d",&x,&y);
        adj[x].push_back(y);
        adj[y].push_back(x);
    }
    vector<int> dist(n+1), par(n+1);
    auto bfs=[&](int s){
        fill(dist.begin(),dist.end(),-1);
        dist[s]=0;
        queue<int> q; q.push(s);
        while(!q.empty()){
            int u=q.front(); q.pop();
            for(int v:adj[u]) if(dist[v]<0){dist[v]=dist[u]+1; par[v]=u; q.push(v);}
        }
    };
    // diametro: dupla BFS
    bfs(1);
    int a=1;
    for(int i=2;i<=n;i++) if(dist[i]>dist[a]) a=i;
    bfs(a);
    int b=a;
    for(int i=1;i<=n;i++) if(dist[i]>dist[b]) b=i;
    int D=dist[b];

    // centro: vertice a distancia floor(D/2) de a ao longo do caminho a..b
    int c=b;
    for(int i=0;i<D-D/2;i++) c=par[c];

    // BFS a partir do centro: profundidade e identificacao da "branch"
    vector<int> dep(n+1,-1), br(n+1,0);
    {
        queue<int> q; q.push(c); dep[c]=0;
        while(!q.empty()){
            int u=q.front(); q.pop();
            for(int v:adj[u]) if(dep[v]<0){
                dep[v]=dep[u]+1;
                br[v]=(u==c? v : br[u]);
                q.push(v);
            }
        }
    }
    // todo par de vertices a distancia D tem caminho passando pelo centro,
    // e os dois extremos estao em branches distintas do centro.
    vector<int> h(n+1,0);
    for(int u=1;u<=n;u++) if(dep[u]>0) h[br[u]]=max(h[br[u]],dep[u]);
    vector<long long> T(D+2,0);
    for(int u=1;u<=n;u++) if(dep[u]>0) T[dep[u]]++;
    vector<int> off(n+1,-1);
    int cur=0;
    for(int r=1;r<=n;r++) if(h[r]>0){ off[r]=cur; cur+=h[r]+1; }
    vector<long long> fdata(cur,0);
    for(int u=1;u<=n;u++) if(dep[u]>0) fdata[off[br[u]]+dep[u]]++;

    // pares ordenados entre branches distintas com delta_u + delta_v = D
    long long cross=0;
    for(int x=1;x<=D;x++) cross += (long long)T[x]*T[D-x];
    // remove pares na mesma branch (esses nao passam pelo centro)
    long long same=0;
    for(int r=1;r<=n;r++){
        if(off[r]<0) continue;
        int hb=h[r];
        int xlo=max(1,D-hb), xhi=min(D-1,hb);
        for(int x=xlo;x<=xhi;x++)
            same += fdata[off[r]+x]*fdata[off[r]+D-x];
    }
    printf("%d\n%lld\n", D+1, (cross-same)/2);
    return 0;
}
